<script setup lang="ts">
import {formatBytes} from './format-bytes';
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {parseHistoryPage,historySources,historyStatuses,historyPhases,historyTimeText,type HistoryRun} from './cloud-history-types';
import {historyRunsURL,historyRequestKey,historyFilterText,type HistoryRoute} from './cloud-history-route';
const props=defineProps<{route:HistoryRoute;disabled:boolean;previousLabel:string}>(),emit=defineEmits<{authenticationRequired:[];next:[string];previous:[];open:[HistoryRun];loaded:[{rows:HistoryRun[];context:string;observedAt:string}]}>();
const rows=ref<HistoryRun[]>([]),loading=ref(false),error=ref(''),observed=ref(''),next=ref('0'),more=ref(false),loadedLabel=ref('');let active=true,generation=0,controller:AbortController|undefined;
function stop(){active=false;generation++;controller?.abort();loading.value=false;}
async function load(){
 if(!active||props.disabled||loading.value)return;const request=++generation,route={...props.route,filters:{...props.route.filters}};controller=new AbortController();loading.value=true;
 try{const response=await fetch(historyRunsURL(route),{credentials:'same-origin',signal:controller.signal});if(request!==generation)return;if(response.status===401){stop();emit('authenticationRequired');return;}if(!response.ok)throw Error(await response.text()||'历史读取失败');const data=await response.json();if(request!==generation)return;const page=parseHistoryPage(data,route.source,route.before);rows.value=page.rows;next.value=page.next;more.value=page.more;error.value='';loadedLabel.value=historySources[route.source]+' · '+historyFilterText(route.filters)+' · 游标 '+route.before;observed.value=new Date().toISOString();emit('loaded',{rows:page.rows,context:historyRequestKey(route),observedAt:observed.value});}
 catch(e:any){if(request===generation)error.value=e.message||'历史暂不可读';}finally{if(request===generation)loading.value=false;}
}
function forceLoad(){generation++;controller?.abort();loading.value=false;load();}
function restore(event:PageTransitionEvent){if(event.persisted&&!props.disabled){active=true;load();}}
watch(()=>historyRequestKey(props.route),forceLoad);watch(()=>props.disabled,value=>{if(value)stop();});onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);load();});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore);});
</script>
<template><section class="event-results" data-testid="history-runs"><header class="page-header"><h2>运行记录</h2><button class="button secondary" :disabled="disabled||loading" @click="load">刷新历史</button></header><p class="muted">这些是本地持久化历史；历史“运行中”不证明当前进程仍有执行器。</p><p v-if="loading" role="status">正在读取历史…</p><p v-if="error" class="notice danger" role="alert">{{error}}<span v-if="observed"> · 下方保留上次读取记录。</span></p><p v-if="loadedLabel" class="muted">下方记录来源：{{loadedLabel}}</p><div class="event-table-scroll"><table><thead><tr><th>运行 ID</th><th>状态 / 阶段</th><th>范围 / 当前路径</th><th>完成量</th><th>开始 UTC</th><th>更新 UTC</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.run_id"><td>{{row.run_id}}</td><td>{{historyStatuses[row.status]||row.status}}<br>{{historyPhases[row.phase]||row.phase}}</td><td>{{row.source==='hash'?'内容哈希候选':row.source==='refresh'?row.root_path:row.current_directory}}</td><td><template v-if="row.source==='hash'">{{row.processed_files}} / {{row.total_files}} 个文件<br>{{formatBytes(row.processed_bytes)}} / {{formatBytes(row.total_bytes)}}</template><template v-else>{{row.items_processed}} 项 / {{row.pages_processed}} 页<br>待处理 {{row.pending_count}} 目录</template></td><td>{{historyTimeText(row.started_at_utc)}}</td><td>{{historyTimeText(row.updated_at_utc)}}</td><td><button class="button secondary" data-testid="history-run-open" :disabled="disabled||loading||!!error" @click="emit('open',row)">查看详情</button></td></tr><tr v-if="!loading&&!rows.length&&!error"><td colspan="7">暂无对应本地运行记录。</td></tr></tbody></table></div><div class="path-impact-pagination"><button class="button secondary" data-testid="history-prev" :disabled="disabled||loading||!!error||route.before==='0'" @click="emit('previous')">{{previousLabel}}</button><button class="button secondary" data-testid="history-next" :disabled="disabled||loading||!!error||!more" @click="emit('next',next)">下一批</button></div><p v-if="observed" class="muted">本机读取 UTC：{{observed}}</p></section></template>
